import logging
from taf.sbts.oam.coam.admin import admin


class custom_utilities:
    """
    # FREQUENCY_RANGES in MHz
        RANGE1 [0 - 3000)
        RANGE2 [3000 - 24250)
        RANGE3 [24250 - 100000)
    """

    FREQUENCY_FORMULA = {
        # (freq start in MHz, freq end in MHz): formula to calculate frequency in MHz from nrarfcn
        'RANGE1': lambda nrarfcn: 5 * nrarfcn / 1000,
        'RANGE2': lambda nrarfcn: 15 * (nrarfcn - 600000) / 1000 + 3000,
        'RANGE3': lambda nrarfcn: 60 * (nrarfcn - 2016667) / 1000 + 24250.08,
    }

    NRARFCN_RANGES = {
        # (freq start in MHz, freq end in MHz): (nrarfcn start, nrarfcn end))
        'RANGE1': (0, 599999),
        'RANGE2': (600000, 2016666),
        'RANGE3': (2016667, 3279166),
    }

    SSB_NUMBERS = {
        # (duplex_type, (freq start in MHz, freq end in MHz)): ssb beam pattern ID
        'FDD': {
            (0, 3000): 'ssb_1'
        },
        'TDD': {
            (0, 3000): 'ssb_4',
            (3001, 6000): 'ssb_8',
            (6001, 60000): 'ssb_32',
        }
    }

    LOAD_LEVEL_MAPPING = {
        'Idle': 'CellsLocked',
        'Low': 'CellsOnAir',
        'Medium': 'load_30_medium',
        'Busy': 'load_50_busy_hour',
        'Full': 'FullLoad',
    }

    LOAD_TYPE_MAPPING = {
        'Idle': 'CellsLocked',
        'Low': 'CellsOnAir',
        'Medium': 'slotWiseLoad',
        'Busy': 'slotWiseLoad',
        'Full': 'flatLoad',
    }

    TM_MAPPING = {
        'Idle': None,
        'Low': None,
        'Medium': 'TM1_1_ETSI',
        'Busy': 'TM1_1_ETSI',
        'Full': 'TM1_1',
    }

    def __init__(self):
        self.admin_cli = admin()

    def generate_test_model_params(self, connection, bts_info=None, cells=None, rus=None,
                                   beam_pattern_id=951, ssb_beam_pattern_id=None):
        test_model_params = []
        if bts_info is None:
            bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=60)

        if cells:
            cells = cells if isinstance(cells, list) else cells.split(',')
        elif cells is None and rus:
            rus = rus if isinstance(rus, list) else rus.split(',')
            ru_cell_relation = self._get_ru_cell_relation(bts_info)
            cells = [cell.split('/')[-1] for ru in rus for cell in ru_cell_relation.get(ru, [])]

        tdd_params = self.admin_cli.get_parameter_by_class(connection=connection, class_name="LNCEL_TDD")

        all_cells = bts_info['cells']['nr'] + bts_info['cells']['lte']
        for cell_info in all_cells:
            cell_name = cell_info['id']['configuration'].split('/')[-1]
            if not cells or cell_name in cells:
                cell_config = self.admin_cli.get_parameter_by_distname(dist_name=cell_info['id']['configuration'],
                                                                       connection=connection, timeout=60)
                if 'NRCELL' in cell_name:
                    cell_params = self._generate_test_model_params_for_5g(
                        cell_name=cell_name,
                        cell_config=cell_config,
                        cell_info=cell_info,
                        beam_pattern_id=beam_pattern_id,
                        ssb_beam_pattern_id=ssb_beam_pattern_id
                    )
                else:
                    cell_params = self._generate_test_model_params_for_lte(
                        cell_name=cell_name,
                        cell_config=cell_config,
                        cell_info=cell_info,
                        tdd_params=tdd_params
                    )
                test_model_params.append(cell_params)
        return test_model_params

    def _generate_test_model_params_for_5g(self, cell_name, cell_config, cell_info,
                                           beam_pattern_id, ssb_beam_pattern_id):
        default_common_params = {
            'test_name': 'NR_DOWNLINK',
            'power_backoff': 0,
            'ru_mode': 'NR_Only',
            'mimo_rank': 1,
            'codebook_2_antports': 0,
            'i11_codebook_4_antports': 0,
            'i2_codebook_4_antports': 0,
            'i13_codebook_4_antports': 0,
            'polarization': 'P_both',
        }

        nrarfcn = cell_info.get('nrarfcnDl') if cell_info['technology'] == 'FDD' else cell_info.get('nrarfcn')
        num_of_ssb_beam_pattern_id = self._get_num_of_ssb_beam_pattern_id(nrarfcn=nrarfcn,
                                                                          duplex_type=cell_info['technology'])
        if ssb_beam_pattern_id is None:
            ssb_beam_pattern_id = self._generate_ssb_beam_pattern_id(
                num_of_ssb_beam_pattern_id=num_of_ssb_beam_pattern_id,
                beam_id=beam_pattern_id)
        cell_params = {
            **default_common_params,
            'dist_name': cell_info['id']['internal'],
            'cell_name': cell_name,
            'global_cell_id': cell_info['globalCellId'],
            'phys_cell_id': cell_info['physicalCellId'],
            'p_max': cell_config[0]['parameters']['pMax'],
            'nrarfcn_dl': nrarfcn,
            'beam_pattern_id': beam_pattern_id,
            'num_of_ssb_beam_pattern_id': num_of_ssb_beam_pattern_id,
            'ssb_beam_pattern_id': ssb_beam_pattern_id,
        }
        return cell_params

    def _generate_test_model_params_for_lte(self, cell_name, cell_config, cell_info, tdd_params):
        additional_params = {}
        if cell_info['technology'] == 'TDD':
            cell_dist_name = cell_info['id']['configuration']
            params = None
            for record in tdd_params:
                rd_dist_name = "/".join(record['distName'].split('/')[:-1])
                if rd_dist_name == cell_dist_name:
                    params = record['parameters']
                    break
            if params:
                additional_params['tdd_frame_conf'] = params['tddFrameConf']
                additional_params['tdd_spec_sub_conf'] = params['tddSpecSubfConf']

        cell_params = {
            'test_name': 'LTE_DOWNLINK',
            'dist_name': cell_info['id']['internal'],
            'cell_name': cell_name,
            'global_cell_id': cell_info['globalCellId'],
            'phys_cell_id': cell_info['physicalCellId'],
            'p_max': cell_config[0]['parameters']['pMax'],
            'earfcn': cell_info.get('earfcnDownlink'),
            **additional_params
        }

        return cell_params

    @staticmethod
    def update_test_model_params(test_model_params, load_level, load_type=None, test_model=None):
        if load_type is None:
            load_type = custom_utilities.LOAD_TYPE_MAPPING.get(load_level)
        if test_model is None:
            nr_test_model = custom_utilities.TM_MAPPING.get(load_level)
            lte_test_model = 'E_' + nr_test_model if nr_test_model else nr_test_model
        else:
            nr_test_model = test_model
            lte_test_model = test_model

        for cell_record in test_model_params:
            if 'NRCELL' in cell_record['dist_name']:
                cell_test_model = nr_test_model
            else:
                cell_test_model = lte_test_model
            cell_record.update(
                {
                    'test_model': cell_test_model,
                    'load_type': load_type,
                    'load_level': custom_utilities.LOAD_LEVEL_MAPPING.get(load_level)
                }
            )

    @staticmethod
    def generate_test_model_params_for_report(load_level, test_model_params, started_dist_names=None):
        test_model_params_for_report = []
        for tm in test_model_params:
            if started_dist_names is None or tm['dist_name'] in started_dist_names:
                test_model_params_for_report.append(
                    {
                        'dist_name': tm['dist_name'],
                        'test_model': tm['test_model'],
                        'p_max': tm['p_max'],
                        'load_type': tm['load_type'],
                        'load_level': custom_utilities.LOAD_LEVEL_MAPPING.get(load_level),
                        'load_level_name': load_level
                    }
                )

        return test_model_params_for_report

    @staticmethod
    def get_cell_dist_names_from_test_model_params(test_model_params):
        cell_dist_names = []
        for tm in test_model_params:
            cell_dist_names.append(tm['dist_name'])
        return cell_dist_names

    @staticmethod
    def _get_ru_cell_relation(bts_info):
        all_ru_rel = {}
        rus_info = [ru for ru_type in bts_info["radioModules"] for ru in bts_info["radioModules"][ru_type]]
        for ru in rus_info:
            ru_dn = ru['id']['configuration']
            ru_name = ru_dn.split('/')[-1]
            all_cells = []
            for carrier in ru['carrierList']:
                cell_dist_name = '/'.join(carrier['id']['configuration'].split('/')[0:-1])
                all_cells.append(cell_dist_name)
            all_ru_rel[ru_name] = list(set(all_cells))
        return all_ru_rel

    @classmethod
    def _get_num_of_ssb_beam_pattern_id(cls, nrarfcn, duplex_type):
        for freq_range, nrarfcn_range in cls.NRARFCN_RANGES.items():
            if nrarfcn_range[0] <= nrarfcn <= nrarfcn_range[1]:
                freq = cls.FREQUENCY_FORMULA.get(freq_range)(nrarfcn)
                logging.debug(f"Used frequency: {freq} MHz")
                for freq_sub_range in cls.SSB_NUMBERS.get(duplex_type, {}):
                    if freq_sub_range[0] <= freq <= freq_sub_range[1]:
                        return cls.SSB_NUMBERS.get(duplex_type).get(freq_sub_range)

    @staticmethod
    def _generate_ssb_beam_pattern_id(num_of_ssb_beam_pattern_id, beam_id=951):
        ssb_number = int(num_of_ssb_beam_pattern_id.split('_')[1])
        list_of_beams = [str(beam_id)] * ssb_number
        ssb_beam_pattern_id = ",".join(list_of_beams)
        logging.debug(f"Generated SSB beam pattern ID: {ssb_beam_pattern_id}")
        return ssb_beam_pattern_id
